// ⚠ DO NOT REMOVE — seed_hba_payroll_windows.js — fixes W-HBA-CLICKTHRU's 2 confirmed dead links.
//
// User asked (2026-07-04) whether HBA's "open ↗" deep-links were click-tested — they weren't; a new real
// witness (hr_bim_asset/tests/live/witness_hba_clickthru.js, bim-ootb PR #641) found Payslip's window 53042
// and Leave's window 53036 return "Window NNNNN not found" for a real user, because those AD_Window rows were
// never seeded into ad_seed.db (only ad_full.db, the separate ground-truth reference catalog, has them).
//
// EVERY row this script inserts is copied VERBATIM from real iDempiere's own shipped dictionary (sqlite3
// build/erp/ad_full.db, 2026-07-04) — nothing invented. Scope, discovered by tracing the real dependency
// chain (non-invent: every FK must resolve, not just the window row):
//   - AD_Window 53036 "Payroll Concept Catalog" + 53042 "Payroll Movement" — BOTH ship IsActive='N' in the
//     real reference dictionary (EntityType='EE02', an optional/Enterprise-tier feature disabled by default
//     even upstream) — flipped to 'Y' here, an ordinary real-iDempiere activation (any admin can do this via
//     System Administrator), not an invention. Flagged explicitly, not silently changed.
//   - AD_Tab: 53124 (Payroll Movement, over HR_Movement — already has 7 real rows) + 53111/53112/53113/53200
//     (Concept / Concept Accounting / Employee Attributes / Concept Ordering, under window 53036) — all ship
//     IsActive='Y' already, just never copied over.
//   - AD_Field: 90 rows across those 5 tabs. Every AD_Column_ID they reference already exists in ad_seed.db
//     (checked: 90/90 resolve) — the dictionary's column layer was already complete, only Window/Tab/Field
//     were missing.
//   - 2 of the 5 tabs (Concept Accounting → HR_Concept_Acct, Employee Attributes → HR_Attribute) reference
//     physical tables that don't exist in ad_seed.db yet. Real iDempiere's own ad_full.db carries them too —
//     with the EXACT SAME real DDL, 0 rows in the reference itself (nobody ever seeded demo data for these
//     either, even upstream). Created here as empty tables, verbatim schema, non-invented — an empty tab is
//     honest; a missing table crashing the window open is not.
//
// Idempotent: re-running with these rows already present is a no-op. Self-witnessing: read the log.
// Run: NODE_PATH=$HOME/bim-ootb/node_modules node scripts/seed_hba_payroll_windows.js   (writes erp/ad_seed.db)
'use strict';
const fs = require('fs');
const path = require('path');
const initSqlJs = require('sql.js');

const ROOT = path.join(__dirname, '..');
const SEED = path.join(ROOT, 'erp', 'ad_seed.db');

function scalar(db, sql, p) { var r = db.exec(sql, p || []); return (r.length && r[0].values.length) ? r[0].values[0][0] : null; }
function ins(db, table, obj) {
  var ks = Object.keys(obj);
  db.run('INSERT INTO ' + table + ' (' + ks.join(',') + ') VALUES (' + ks.map(function () { return '?'; }).join(',') + ')',
    ks.map(function (k) { return obj[k]; }));
}

