// real DDL verbatim from ad_full.db sqlite_master (2026-07-04) — 0 rows in the reference too, empty is honest.
const EXTRA_TABLES = {
  hr_attribute: 'CREATE TABLE "hr_attribute" ("ad_client_id" NUMERIC, "ad_org_id" NUMERIC, "ad_rule_id" NUMERIC, "amount" NUMERIC, "c_bpartner_id" NUMERIC, "columntype" TEXT, "created" TEXT, "createdby" NUMERIC, "description" TEXT, "hr_attribute_acct" NUMERIC, "hr_attribute_id" NUMERIC, "hr_concept_id" NUMERIC, "hr_department_id" NUMERIC, "hr_employee_id" NUMERIC, "hr_job_id" NUMERIC, "hr_payroll_id" NUMERIC, "isactive" TEXT, "isprinted" TEXT, "maxvalue" NUMERIC, "minvalue" NUMERIC, "qty" NUMERIC, "servicedate" TEXT, "textmsg" TEXT, "updated" TEXT, "updatedby" NUMERIC, "validfrom" TEXT, "validto" TEXT, "hr_attribute_uu" TEXT)',
  hr_concept_acct: 'CREATE TABLE "hr_concept_acct" ("c_bp_group_id" NUMERIC, "isbalancing" TEXT, "user1_id" NUMERIC, "user2_id" NUMERIC, "createdby" NUMERIC, "hr_concept_acct_id" NUMERIC, "hr_concept_id" NUMERIC, "ad_client_id" NUMERIC, "hr_revenue_acct" NUMERIC, "isactive" TEXT, "updated" TEXT, "updatedby" NUMERIC, "hr_expense_acct" NUMERIC, "ad_org_id" NUMERIC, "c_acctschema_id" NUMERIC, "created" TEXT, "hr_concept_acct_uu" TEXT)',
};

(async function () {
  var fails = 0;
  function L(m) { console.log(m); }
  function must(tag, cond, msg) { L('§W-HBA-PAYROLL-WIN-SEED ' + (cond ? 'PASS' : 'FAIL') + ' ' + tag + ' — ' + msg); if (!cond) fails++; }

  if (!fs.existsSync(SEED)) { L('§SEED_HBA_PWIN FAIL — erp/ad_seed.db not found at ' + SEED); process.exit(1); }
  const SQL = await initSqlJs();
  const db = new SQL.Database(fs.readFileSync(SEED));
  var added = { tables: 0, windows: 0, tabs: 0, fields: 0 };

  // ── 1. the 2 empty physical tables (verbatim DDL) ──────────────────────────────────────────────────────
  Object.keys(EXTRA_TABLES).forEach(function (t) {
    if (!db.exec("SELECT name FROM sqlite_master WHERE type='table' AND lower(name)=lower('" + t + "')").length) {
      db.run(EXTRA_TABLES[t]); added.tables++; L('§SEED_HBA_PWIN_DDL CREATE ' + t + ' (verbatim ad_full.db schema, 0 rows — matches the reference)');
    }
  });

  // ── 2. AD_Window rows — activate on insert (real EE02 feature, shipped IsActive='N' even upstream) ──────
  WINDOWS.forEach(function (w) {
    if (scalar(db, 'SELECT AD_Window_ID FROM AD_Window WHERE AD_Window_ID=?', [w.ad_window_id]) != null) {
      L('§SEED_HBA_PWIN_WINDOW SKIP ' + w.ad_window_id + ' (' + w.name + ') already present'); return;
    }
    var row = Object.assign({}, w);
    row.isactive = 'Y';   // §ACTIVATE — real upstream ships this 'N' (EE02 optional tier); flipped, not invented
    ins(db, 'AD_Window', row); added.windows++;
    L('§SEED_HBA_PWIN_WINDOW ADD ' + w.ad_window_id + ' "' + w.name + '" IsActive N→Y (was inactive upstream too)');
  });

  // ── 3. AD_Tab rows — already IsActive=Y upstream, copied verbatim ─────────────────────────────────────
  TABS.forEach(function (t) {
    if (scalar(db, 'SELECT AD_Tab_ID FROM AD_Tab WHERE AD_Tab_ID=?', [t.ad_tab_id]) != null) {
      L('§SEED_HBA_PWIN_TAB SKIP ' + t.ad_tab_id + ' (' + t.name + ') already present'); return;
    }
    ins(db, 'AD_Tab', t); added.tabs++;
    L('§SEED_HBA_PWIN_TAB ADD ' + t.ad_tab_id + ' "' + t.name + '" window=' + t.ad_window_id + ' table=' + t.ad_table_id);
  });

  // ── 4. AD_Field rows — 90 rows, every AD_Column_ID independently confirmed to already resolve ──────────
  FIELDS.forEach(function (f) {
    if (scalar(db, 'SELECT AD_Field_ID FROM AD_Field WHERE AD_Field_ID=?', [f.ad_field_id]) != null) return;
    ins(db, 'AD_Field', f); added.fields++;
  });
  L('§SEED_HBA_PWIN_FIELD added=' + added.fields + '/' + FIELDS.length + ' (skipped = already present, idempotent 2nd run)');

  // ── 5. self-witness — the exact chain the live browser walks (AD_PARSER getWindow→getTabs→getFields) ────
  must('WINDOW-236-UNTOUCHED', scalar(db, "SELECT Name FROM AD_Window WHERE AD_Window_ID=236") === 'Resource',
    'the ALREADY-WORKING window 236 is untouched by this script (no regression)');
  [53036, 53042].forEach(function (wid) {
    var w = scalar(db, 'SELECT Name FROM AD_Window WHERE AD_Window_ID=? AND IsActive=?', [wid, 'Y']);
    must('WINDOW-' + wid + '-ACTIVE', !!w, 'AD_Window ' + wid + ' present + IsActive=Y — "' + w + '"');
  });
  var tabCount53036 = Number(scalar(db, 'SELECT COUNT(*) FROM AD_Tab WHERE AD_Window_ID=53036'));
  must('TABS-53036', tabCount53036 === 4, 'window 53036 carries all 4 real tabs (Concept/Concept Accounting/Employee Attributes/Concept Ordering) — got ' + tabCount53036);
  var tabCount53042 = Number(scalar(db, 'SELECT COUNT(*) FROM AD_Tab WHERE AD_Window_ID=53042'));
  must('TABS-53042', tabCount53042 === 1, 'window 53042 carries its 1 real tab (Payroll Movement) — got ' + tabCount53042);
  var fieldCount = Number(scalar(db, 'SELECT COUNT(*) FROM AD_Field WHERE AD_Tab_ID IN (53124,53111,53112,53113,53200)'));
  must('FIELDS-ALL', fieldCount === 90, 'all 90 real fields present across the 5 tabs — got ' + fieldCount);
  // every field's AD_Column_ID resolves (no dangling FK — the non-invent gate for this script)
  var dangling = Number(scalar(db, 'SELECT COUNT(*) FROM AD_Field F WHERE F.AD_Tab_ID IN (53124,53111,53112,53113,53200)'
    + ' AND NOT EXISTS (SELECT 1 FROM AD_Column C WHERE C.AD_Column_ID=F.AD_Column_ID)'));
  must('NO-DANGLING-FK', dangling === 0, 'every AD_Field.AD_Column_ID resolves to a real AD_Column row — dangling=' + dangling);
  // the actual data these windows point at is unchanged and still real (HR_Movement/HR_Concept rows exist)
  var hrmCount = Number(scalar(db, 'SELECT COUNT(*) FROM HR_Movement'));
  var hrcCount = Number(scalar(db, 'SELECT COUNT(*) FROM HR_Concept'));
  must('DATA-STILL-REAL', hrmCount > 0 && hrcCount > 0, 'HR_Movement=' + hrmCount + ' HR_Concept=' + hrcCount + ' rows unaffected by this script');

  // ── write-back ────────────────────────────────────────────────────────────────────────────────────────
  var changed = added.tables + added.windows + added.tabs + added.fields;
  if (changed > 0 && fails === 0) { fs.writeFileSync(SEED, Buffer.from(db.export())); L('§SEED_HBA_PWIN WROTE erp/ad_seed.db (' + changed + ' additions)'); }
  else if (fails === 0) L('§SEED_HBA_PWIN NO-OP — seed already current (idempotent 2nd run)');
  else L('§SEED_HBA_PWIN NOT WRITTEN — ' + fails + ' witness failure(s), DB left untouched');
  L('§W-HBA-PAYROLL-WIN-SEED ' + (fails === 0 ? 'PASS' : 'FAIL') + ' — summary ' + JSON.stringify(added));
  db.close();
  process.exit(fails === 0 ? 0 : 1);
})();
